        p = self._path(key)
        if not os.path.exists(p):
            return default
        try:
            with open(p) as f:
                rec = json.load(f)
        except json.JSONDecodeError:
            os.remove(p) # Corrupted file
            return default

        # Check if the entry is expired
        if self._now() - rec["t"] > self.ttl:
            os.remove(p)  # Remove expired entry
            return default
        return rec["v"]

    def cleanup(self):
        for fname in os.listdir(self.root):
            if fname.endswith(".json"):
                p = os.path.join(self.root, fname)
                try:
                    with open(p) as f:
                        rec = json.load(f)
                    if self._now() - rec["t"] > self.ttl:
                        os.remove(p)
                except (json.JSONDecodeError, FileNotFoundError):
                    # Ignore files that are corrupted or already removed
                    pass
